#include "insulated_thermal_qualification_model.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace insulated_thermal;
namespace {
struct Checks {std::ofstream stream;std::size_t count{};explicit Checks(const std::filesystem::path& p):stream(p){stream<<std::setprecision(17)<<"name,error,tolerance,passed\n";}void operator()(std::string name,double error,double tolerance){++count;bool pass=std::isfinite(error)&&error<=tolerance;stream<<name<<','<<error<<','<<tolerance<<','<<pass<<'\n';if(!pass)throw std::runtime_error(name+": "+std::to_string(error));}};
double matrix_error(Mat<2,2> a,Mat<2,2> b){return std::max(norm(a[0]-b[0]),norm(a[1]-b[1]));}
Mat<2,2> hessian(const System<2,2>& sys,Vec<2> x){Mat<2,2> H{};for(int j=0;j<2;++j){Vec<2> v{};v[j]=1.;auto h=sys.hessian_vector(x,v);for(int i=0;i<2;++i)H[i][j]=h[i];}return H;}
void optional(std::ostream& s,std::optional<double> t){if(t)s<<*t;}
}
int main(int argc,char** argv){try{
 std::filesystem::path out=argc>1?argv[1]:"results/insulated_thermal";std::filesystem::create_directories(out);Checks check(out/"checks.csv");
 std::ofstream summary(out/"summary.csv");summary<<std::setprecision(17)<<"quantity,value\n";auto report=[&](std::string key,double value){summary<<key<<','<<value<<'\n';std::cout<<std::setprecision(12)<<key<<": "<<value<<'\n';};
 report("difference_decay_rate_per_min",rate);report("true_weighted_mean_degC",dot(mean,truth));
 auto analytic=analytical_fit();report("analytical_baseline_t10_degC",analytic[0]);report("analytical_baseline_t20_degC",analytic[1]);
 check("analytical invariant mean",std::abs(dot(mean,exact(3.,truth))-dot(mean,truth)),2e-14);check("analytical common mode persists",norm(exact(7.,common)-common),1e-14);
 check("noiseless absolute-datum recovery",norm(analytical_fit(true,seed,false)-truth),2e-14);
 auto info=information(false),fullinfo=information(true);auto spectrum=psd_spectrum_2d(info);check("analytical missing information rank",std::abs(static_cast<double>(spectrum.rank)-1.),0.);check("analytical null direction",norm(mv(info,common)),2e-13);check("added datum restores analytical rank",std::abs(static_cast<double>(psd_spectrum_2d(fullinfo).rank)-2.),0.);
 constexpr std::size_t quantities=12;std::array<const char*,quantities> names{"state","tangent","observation_adjoint","observation_cost","observation_gradient","observation_hessian","initial_difference","representative_control","running_cost","running_gradient","running_costate","running_hessian"};
 std::ofstream convergence(out/"convergence.csv"),orders(out/"orders.csv"),fits(out/"fits.csv"),traces(out/"optimizer_trace.csv");convergence<<std::setprecision(17)<<"added,theta,steps,h_min";for(auto name:names)convergence<<','<<name;convergence<<'\n';orders<<std::setprecision(17)<<"added,theta,quantity,order\n";fits<<std::setprecision(17)<<"added,theta,steps,t10,t20,analytical_t10,analytical_t20,rank\n";traces<<std::setprecision(17)<<"added,iteration,t10,t20,cost,gradient_norm\n";
 for(bool added:{false,true})for(double theta:{.5,.65}){std::array<double,quantities> previous{},errors{};for(std::size_t steps:{32u,64u,128u,256u,512u}){
  auto sys=system(steps,theta,added);auto ev=sys.evaluate(probe);auto result=fit(sys);auto optimum=result.optimum.control;auto reference=analytical_fit(added);auto H=hessian(sys,probe);auto exactH=information(added);auto run=system(steps,theta,false,true);auto re=run.evaluate(probe);auto rcostate=run.cost_to_go_adjoint(probe,re);auto Q=gramian(horizon);auto Qd=hessian(run,probe);Vec<2> direction{.8,-.3};auto tangent=sys.tangent(probe,ev.trajectory,direction);auto neutral=sys.tangent(probe,ev.trajectory,common);
  check("discrete rank matches physical information",std::abs(static_cast<double>(result.spectrum.rank)-(added?2.:1.)),0.);check("projected optimum is stationary",norm(sys.evaluate(optimum).gradient),1e-8);check("discrete forward residual",ev.trajectory.max_residual,2e-12);check("discrete Hessian symmetry",std::abs(H[0][1]-H[1][0]),2e-10);
  double state_error=0.,tangent_error=0.,adj_error=0.,adj_scale=0.,run_error=0.,run_scale=0.,invariant=0.,neutral_error=0.,modal_error=0.,balance=0.;double factor=(1-(1-theta)*rate*horizon/steps)/(1+theta*rate*horizon/steps);
  for(std::size_t n=0;n<=steps;++n){double tau=sys.grid().time[n]-t0;auto x=exact(tau,probe),la=nodal_costate(tau,probe,added),lr=running_costate(tau,probe);state_error=std::max(state_error,norm(ev.trajectory.state[n]-x));tangent_error=std::max(tangent_error,norm(tangent[n]-exact(tau,direction)));adj_error=std::max(adj_error,norm(ev.nodal_adjoint[n]-la));adj_scale=std::max(adj_scale,norm(la));run_error=std::max(run_error,norm(rcostate[n]-lr));run_scale=std::max(run_scale,norm(lr));invariant=std::max(invariant,std::abs(energy(ev.trajectory.state[n])-energy(probe)));neutral_error=std::max(neutral_error,norm(neutral[n]-common));double d=dot(difference,probe)*std::pow(factor,static_cast<double>(n));double m=dot(mean,probe);modal_error=std::max(modal_error,norm(ev.trajectory.state[n]-Vec<2>{m+w2*d,m-w1*d}));if(n)balance=std::max(balance,std::abs(energy(ev.trajectory.state[n])-energy(ev.trajectory.state[n-1])));}
  check("total heat invariant",invariant,2e-10);check("theta heat balance per step",balance,2e-12);check("neutral tangent preserved at every node",neutral_error,1e-12);check("forward versus independent modal theta recurrence",modal_error,3e-11);check("terminal observation adjoint zero",norm(ev.nodal_adjoint.back()),1e-15);check("terminal running costate zero",norm(rcostate.back()),1e-15);
  if(!added){check("measurement gradient annihilates common offset",std::abs(dot(ev.gradient,common)),1e-10);check("incremental adjoint annihilates common offset",norm(sys.hessian_vector(probe,common)),1e-10);check("optimizer preserves seed arithmetic mean",std::abs(.5*(optimum[0]+optimum[1])-.5*(seed[0]+seed[1])),2e-12);}
  previous=errors;auto eg=exact_gradient(probe,added);auto rg=mv(Q,probe);double J=.5*dot(probe,rg);errors={state_error,tangent_error,adj_error/adj_scale,std::abs(ev.cost-exact_cost(probe,added))/exact_cost(probe,added),norm(ev.gradient-eg)/norm(eg),matrix_error(H,exactH)/std::max(norm(exactH[0]),norm(exactH[1])),std::abs(dot(difference,optimum-reference)),norm(optimum-reference),std::abs(re.cost-J)/J,norm(re.gradient-rg)/norm(rg),run_error/run_scale,matrix_error(Qd,Q)/std::max(norm(Q[0]),norm(Q[1]))};
  convergence<<added<<','<<theta<<','<<steps<<','<<horizon/steps;for(auto e:errors)convergence<<','<<e;convergence<<'\n';fits<<added<<','<<theta<<','<<steps<<','<<optimum[0]<<','<<optimum[1]<<','<<reference[0]<<','<<reference[1]<<','<<result.spectrum.rank<<'\n';
  if(!added&&theta==.5&&steps==128){std::ofstream costates(out/"costates.csv");costates<<std::setprecision(17)<<"elapsed_min,discrete1,discrete2,analytical1,analytical2\n";for(std::size_t n=0;n<rcostate.size();++n){double tau=run.grid().time[n]-t0;auto ref=running_costate(tau,probe);costates<<tau<<','<<rcostate[n][0]<<','<<rcostate[n][1]<<','<<ref[0]<<','<<ref[1]<<'\n';}}
  if(theta==.5&&steps==128){double epsilon=1e-4;auto plus=sys.evaluate(probe+epsilon*direction),minus=sys.evaluate(probe-epsilon*direction);check("cost finite-difference adjoint",std::abs((plus.cost-minus.cost)/(2*epsilon)-dot(ev.gradient,direction)),2e-6);check("gradient finite-difference incremental adjoint",norm((1/(2*epsilon))*(plus.gradient-minus.gradient)-sys.hessian_vector(probe,direction)),3e-6);double paired=0.;for(auto o:observations(added)){auto n=node_at(sys.grid(),o.tau);paired+=(dot(o.goal,ev.trajectory.state[n])-o.value)*dot(o.goal,tangent[n])/(o.scale*o.scale);}check("tangent adjoint pairing",std::abs(paired-dot(ev.gradient,direction)),1e-9);
   for(std::size_t j=0;j<result.optimum.trace.size();++j){auto it=result.optimum.trace[j];traces<<added<<','<<j<<','<<it.control[0]<<','<<it.control[1]<<','<<it.cost<<','<<it.gradient_norm<<'\n';}
  }
 }
 for(std::size_t j=0;j<quantities;++j){double order=std::log2(previous[j]/errors[j]);orders<<added<<','<<theta<<','<<names[j]<<','<<order<<'\n';check(std::string("temporal order ")+names[j],std::abs(order-(theta==.5?2.:1.)),theta==.5?.04:.09);}
 }
 // Missing directions and distinct equally good fits: no false uniqueness.
 auto baseline=system(512,.5);auto first=fit(baseline),second=fit(baseline,seed+4.*common);check("distinct optimizer representatives",norm(second.optimum.control-first.optimum.control-4.*common),2e-11);check("equal fit costs along common mode",std::abs(baseline.evaluate(second.optimum.control).cost-baseline.evaluate(first.optimum.control).cost),2e-11);
 auto full=system(512,.5,true);check("added data removes seed dependence",norm(fit(full).optimum.control-fit(full,seed+4.*common).optimum.control),3e-11);
 bool rejected=false;try{first.spectrum.solve_compatible(common);}catch(const std::domain_error&){rejected=true;}check("cannot invert missing measurement information",rejected?0.:1.,0.);
 auto map=control_to_state_jacobians(baseline,probe,baseline.forward(probe));double missing=0.;for(auto o:observations()){auto row=mv(transpose(map[node_at(baseline.grid(),o.tau)]),o.goal);missing=std::max(missing,std::abs(dot(row,common)));}check("observation tangent maps expose missing common mode",missing,2e-12);
 // Retain multiple fitted trajectories and their phase-plane paths.
 std::ofstream trajectories(out/"trajectories.csv"),observed(out/"observations.csv");trajectories<<std::setprecision(17)<<"case,elapsed_min,true_t1,true_t2,exact_fit_t1,exact_fit_t2,discrete_t1,discrete_t2,true_mean,discrete_mean,discrete_difference,exact_difference\n";observed<<std::setprecision(17)<<"added,elapsed_min,goal,value,scale\n";
 for(bool added:{false,true})for(auto o:observations(added))observed<<added<<','<<o.tau<<','<<(o.goal==difference?"difference":"temperature1")<<','<<o.value<<','<<o.scale<<'\n';
 for(int variant=0;variant<3;++variant){bool added=variant==2;Vec<2> start=variant==1?seed+4.*common:seed;auto sys=system(128,.5,added);auto control=fit(sys,start).optimum.control;auto path=sys.forward(control);auto exact_control=analytical_fit(added,start);for(std::size_t n=0;n<path.state.size();++n){double tau=sys.grid().time[n]-t0;auto x=exact(tau,truth),ref=exact(tau,exact_control),v=path.state[n];trajectories<<(variant==0?"difference_only":variant==1?"shifted_seed":"added_absolute")<<','<<tau<<','<<x[0]<<','<<x[1]<<','<<ref[0]<<','<<ref[1]<<','<<v[0]<<','<<v[1]<<','<<dot(mean,x)<<','<<dot(mean,v)<<','<<dot(difference,v)<<','<<dot(difference,ref)<<'\n';}}
 std::ofstream modes(out/"modes.csv");modes<<std::setprecision(17)<<"added,rank,largest_eigenvalue,smallest_eigenvalue,null_t1,null_t2\n";for(bool added:{false,true}){auto sys=system(512,.5,added);auto s=fit(sys).spectrum;modes<<added<<','<<s.rank<<','<<s.eigenvalues[0]<<','<<s.eigenvalues[1]<<','<<s.directions[1][0]<<','<<s.directions[1][1]<<'\n';}
 namespace q=insulated_thermal::qualification;
 std::ofstream decisions(out/"qualification_decisions.csv"),envelopes(out/"qualification_envelopes.csv"),polygons(out/"qualification_polygons.csv");decisions<<std::setprecision(17)<<"case,theta,steps,goal,units,tolerance,qualified,persistent_min,analytical_min,joint_qualified,joint_min\n";envelopes<<std::setprecision(17)<<"case,elapsed_min,end_min,goal,tolerance,whole_bound,analytical_bound,numerical_allowance\n";polygons<<std::setprecision(17)<<"case,set,vertex,t10,t20\n";
 struct Spec {const char* name;std::size_t steps;double theta;bool added;Vec<2> start;};
 std::cout<<"\nINSULATED THERMAL ENGINEERING QUALIFICATION\nDifference tolerance 0.05 K; absolute temperatures 0.3 degC; mean 0.2 degC.\nRetrospective whole-interval decisions through 8 elapsed minutes.\n";
 for(auto spec:std::array<Spec,5>{{{"difference_coarse",32,.5,false,seed},{"difference_refined",512,.5,false,seed},{"difference_theta65",512,.65,false,seed},{"shifted_seed",512,.5,false,seed+4.*common},{"added_absolute",512,.5,true,seed}}}){auto sys=system(spec.steps,spec.theta,spec.added);auto r=q::experiment(sys,spec.added,spec.start,[&](auto name,double error,double tol){check(std::string(spec.name)+": "+name,error,tol);});
  check(std::string(spec.name)+" joint verdict",static_cast<bool>(r.decision.joint)==spec.added?0.:1.,0.);for(std::size_t k=0;k<4;++k){bool expected=spec.added||(k==2&&spec.steps>32&&spec.theta==.5);check(std::string(spec.name)+" expected goal verdict",static_cast<bool>(r.decision.persistent[k])==expected?0.:1.,0.);decisions<<spec.name<<','<<spec.theta<<','<<spec.steps<<','<<q::names[k]<<','<<q::units[k]<<','<<q::tolerances[k]<<','<<static_cast<bool>(r.decision.persistent[k])<<',';optional(decisions,r.decision.persistent[k]);decisions<<',';optional(decisions,r.analytical_time[k]);decisions<<','<<static_cast<bool>(r.decision.joint)<<',';optional(decisions,r.decision.joint);decisions<<'\n';std::cout<<spec.name<<" / "<<q::names[k]<<": ";if(r.decision.persistent[k])std::cout<<"QUALIFIED from "<<*r.decision.persistent[k]<<" min\n";else std::cout<<"NOT QUALIFIED\n";}
  if(spec.added){check("added datum establishes absolute temperatures from start",r.decision.persistent[0].value_or(-1.)+r.decision.persistent[1].value_or(-1.)+r.decision.persistent[3].value_or(-1.),0.);check("difference remains joint limiting goal",std::abs(r.decision.joint.value_or(-1.)-r.decision.persistent[2].value_or(-2.)),0.);}
  std::cout<<spec.name<<" / ALL GOALS: ";if(r.decision.joint)std::cout<<"QUALIFIED from "<<*r.decision.joint<<" min\n";else std::cout<<"NOT QUALIFIED\n";
  for(std::size_t n=0;n<sys.grid().steps();++n)for(std::size_t k=0;k<4;++k){double tau=sys.grid().time[n]-t0;envelopes<<spec.name<<','<<tau<<','<<sys.grid().time[n+1]-t0<<','<<q::names[k]<<','<<q::tolerances[k]<<','<<r.whole[n][k]<<','<<q::exact_bound(tau,r.reference,analytical_fit(spec.added,spec.start),q::goals[k])<<','<<r.error[n]<<'\n';}
  for(bool ref:{false,true}){auto& p=ref?r.reference:r.polygon;for(std::size_t j=0;j<p.size();++j)polygons<<spec.name<<','<<(ref?"analytical":"outer")<<','<<j<<','<<p[j][0]<<','<<p[j][1]<<'\n';}
  if(!spec.added){check("truth plus common offset remains feasible",polygon_contains(r.reference,truth-2.*common)?0.:1.,0.);check("persistent common shift exceeds absolute tolerance",std::abs(exact(horizon,truth)[0]-exact(horizon,truth-2.*common)[0])>q::tolerances[0]?0.:1.,0.);}
 }
 report("checks_passed",static_cast<double>(check.count));std::cout<<"Validation PASS. An unqualified absolute state is the expected baseline result.\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
